INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (436, 1, '인자 하나', '`ethtool eth0` 처럼 **장치 이름만** 주면 무엇을 할까요?', '현재 상태를 보여 줘요.', NULL, NULL, '[]', 'choice', '["드라이버를 다시 올린다", "링크를 자동으로 재협상한다", "현재 설정을 출력한다", "통계 카운터를 초기화한다"]', 2, 'ethtool 문서는 장치 이름 하나만 주면 그 장치의 현재 설정을 출력한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 2, 'speed 단위', '`ethtool -s eth0 speed 1000` 에서 speed 의 **단위** 는 무엇일까요?', '초당 메가비트예요.', NULL, NULL, '[]', 'choice', '["Gb/s", "Mb/s", "MB/s", "kb/s"]', 1, '문서는 speed 를 Mb/s 단위로 설정한다고 설명합니다. duplex 는 full·half, autoneg 는 자동 협상 여부입니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 3, 'wol g', 'wol 옵션 문자 `g` 는 무엇일까요?', 'Magic 패킷이에요.', NULL, NULL, '[]', 'choice', '["MagicPacket 으로 깨운다", "유니캐스트 메시지로 깨운다", "브로드캐스트 메시지로 깨운다", "아무것도 안 깨운다"]', 0, '문서는 g 가 MagicPacket 으로 깨우기(wake on MagicPacket)라고 설명합니다. u 는 유니캐스트, b 는 브로드캐스트입니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 4, 'wol d', 'wol 옵션 문자 `d` 는 무엇일까요?', 'disable 이에요.', NULL, NULL, '[]', 'choice', '["PHY 활동으로 깨운다", "멀티캐스트로 깨운다", "SecureOn 비밀번호를 켠다", "깨우기를 끈다"]', 3, '문서는 d 를 비활성화(아무것으로도 깨우지 않음)라고 설명합니다. p 는 PHY 활동, m 은 멀티캐스트, s 는 SecureOn 비밀번호입니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 5, '-k 와 -K', '`ethtool -k` 와 `-K` 의 차이는 무엇일까요?', '소문자는 조회, 대문자는 변경이에요.', NULL, NULL, '[]', 'choice', '["-k 는 변경, -K 는 조회", "둘 다 조회이고 출력 형식만 다르다", "-k 는 오프로드 상태 조회, -K 는 변경", "둘 다 변경이고 대상 장치만 다르다"]', 2, '문서는 -k 가 프로토콜 오프로드 등 기능 상태를 조회하고 -K 가 그 기능을 변경한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 6, '-i 옵션', '`ethtool -i` 는 무엇을 보여 줄까요?', 'driver 예요.', NULL, NULL, '[]', 'choice', '["링 버퍼 크기", "장치와 연결된 드라이버 정보", "하드웨어 통계 카운터", "모듈 EEPROM 내용"]', 1, '문서는 -i/--driver 가 장치와 연결된 드라이버 정보를 조회한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 7, '-P 옵션', '`ethtool -P` 는 무엇을 조회할까요?', '고정된 하드웨어 주소예요.', NULL, NULL, '[]', 'choice', '["영구 하드웨어 주소", "현재 설정된 MAC 주소", "장치의 IP 주소", "링크 속도"]', 0, '문서는 -P/--show-permaddr 가 장치의 영구(permanent) 하드웨어 주소를 조회한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 8, '-p 옵션', '`ethtool -p eth0 10` 은 무엇을 할까요?', '눈으로 장치를 찾아요.', NULL, NULL, '[]', 'choice', '["10초 동안 통계 카운터를 모은다", "10초 후 장치를 재시작한다", "10초마다 링크 상태를 점검한다", "10초 동안 장치를 식별하게 한다"]', 3, '문서는 -p/--identify 가 운영자가 장치를 눈으로 쉽게 식별하도록 어댑터별 동작을 일으키며 N 은 초 단위 시간이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 9, '-m 옵션', '`ethtool -m` 은 무엇을 읽을까요?', 'SFP+ 같은 모듈이에요.', NULL, NULL, '[]', 'choice', '["장치 펌웨어의 버전 정보", "수신 해시 키 테이블", "플러그인 모듈의 EEPROM", "링 버퍼의 현재 크기"]', 2, '문서는 -m/--dump-module-eeprom 이 SFP+, QSFP 같은 플러그인 모듈의 EEPROM 을 읽고 가능하면 해석한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 10, '설정 변경', '장치 설정을 **변경하는** 옵션입니다. 빈칸을 채우세요.', '소문자 s 예요.', NULL, NULL, '[]', 'fill', '["-s", "-S", "-K", "-p"]', NULL, '-s/--change 는 속도·duplex·autoneg 같은 설정을 바꿉니다. 대문자 -S 는 통계 조회입니다.', '[0]', 'ethtool {0} eth0 speed 1000 duplex full autoneg off', NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 11, '영구 주소', '장치의 **영구 하드웨어 주소** 를 조회하는 옵션입니다. 빈칸을 채우세요.', '대문자 P 예요.', NULL, NULL, '[]', 'fill', '["-P", "-i", "-m", "-t"]', NULL, '-P 는 영구 하드웨어 주소를 조회합니다. -i 는 드라이버, -m 은 모듈 EEPROM 입니다.', '[0]', 'ethtool {0} eth0', NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]'),
  (436, 12, '오프로드 점검', '오프로드 기능을 확인하고 바꾸는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '설정 → 조회 → 변경 → 재조회예요.', NULL, NULL, '[]', 'order', '["`ethtool eth0` 로 현재 링크 설정을 확인한다", "`ethtool -k eth0` 로 오프로드 상태를 조회한다", "`ethtool -K eth0 gro off` 로 기능을 변경한다", "`ethtool -k eth0` 로 바뀐 상태를 다시 조회한다"]', NULL, '문서의 -k·-K 설명을 이은 일반 절차입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "ethtool(8) man page", "url": "https://man7.org/linux/man-pages/man8/ethtool.8.html"}]');
